def colorable(g: Graph, k: int) -> Optional[dict[int, int]]:
    order = sorted(g, key=lambda v: -len(g[v])); c: dict[int, int] = {}
    def go(i: int) -> bool:
        if i == len(order): return True
        v = order[i]
        for x in range(k):
            if all(c.get(u) != x for u in g[v]):
                c[v] = x
                if go(i + 1): return True
                del c[v]
        return False
    return dict(c) if go(0) else None

g = graph()
for k in range(1, 6):
    witness = colorable(g, k)
    print(k, "registers:", "feasible" if witness else "infeasible", witness or "")

