def bipartite(g: Graph) -> bool:
    colors: dict[int, int] = {}
    for start in g:
        if start in colors: continue
        colors[start] = 0; stack = [start]
        while stack:
            v = stack.pop()
            for u in g[v]:
                if u not in colors:
                    colors[u] = 1 - colors[v]; stack.append(u)
                elif colors[u] == colors[v]: return False
    return True

