        def search(i: int) -> bool:
            if i == len(order): return True
            v = order[i]
            for color in range(k):
                if all(colors.get(u) != color for u in g[v]):
                    colors[v] = color
                    if search(i + 1): return True
                    del colors[v]
            return False
        if search(0): return k, dict(colors)
    raise RuntimeError("unreachable")

print(exact_coloring(graph()))

