    return g

def remove(g: Graph, v: int) -> Graph:
    return {u: ns - {v} for u, ns in g.items() if u != v}

def is_bipartite(g: Graph) -> bool:
    c: dict[int, int] = {}
    for s in g:
        if s in c: continue
        c[s] = 0; queue = [s]
        for v in queue:
            for u in g[v]:
                if u not in c: c[u] = 1-c[v]; queue.append(u)
                elif c[u] == c[v]: return False
    return True

def evaluate_spills(g: Graph) -> list[tuple[int, int, bool]]:
    return [(v, len(g[v]), is_bipartite(remove(g, v))) for v in sorted(g)]

